'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,cents} from '@/lib/pilot';
import {billingDollars} from './billing-accounts';
import {readActiveCashiers} from '@/lib/cashier-active';
import {paymentSources,type PaymentSource,paymentArgs,paymentReceipt,paymentRequest,paymentStatus,type PaymentRequest,type PaymentScope} from '@/lib/billing-payment-entry';
type Props=PaymentScope&{cashierSession?:string;onSaved:(id:string,kind:PaymentRequest["kind"])=>void;onBusyChange?:(busy:boolean)=>void};
export function RecordBillingPayment(props:Props){return <PaymentForm key={[props.actor,props.tenant,props.property,props.account].join('/')} {...props}/>}
function PaymentForm(props:Props){
 const key=['irp-company-payment',props.actor,props.tenant,props.property,props.account].join('/');
 const [initial]=useState(()=>{try{const raw=sessionStorage.getItem(key);return {pending:raw?paymentRequest(JSON.parse(raw),props):null,error:''}}catch{return {pending:null,error:'Saved payment could not be read. Restore browser storage before continuing.'}}});
 const [pending,setPending]=useState<PaymentRequest|null>(initial.pending),[draft,setDraft]=useState<PaymentRequest|null>(null);
 const [kind,setKind]=useState<'external_payment'|'external_refund'>('external_payment'),[sources,setSources]=useState<PaymentSource[]>([]),[target,setTarget]=useState('');
 const [method,setMethod]=useState<'external'|'cash'>('external'),[amount,setAmount]=useState(''),[reference,setReference]=useState(''),[reason,setReason]=useState(''),[cancelReason,setCancelReason]=useState('');
 const [cashier,setCashier]=useState<{session:string;drawer:string}|null>(props.cashierSession?{session:props.cashierSession,drawer:'Assigned drawer'}:null);
 const [busy,setBusy]=useState(false),[error,setError]=useState(initial.error),[notice,setNotice]=useState(''),[done,setDone]=useState(false);
 const lock=useRef(false),alive=useRef(false);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 useEffect(()=>{props.onBusyChange?.(busy);return()=>props.onBusyChange?.(false)},[busy,props.onBusyChange]);
 async function run(action:()=>Promise<void>){if(lock.current||initial.error)return;lock.current=true;setBusy(true);setError('');try{await action()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Payment action failed.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function loadReceipts(){setSources([]);setTarget('');const rows=paymentSources(await hotelRpc('billing_payment_receipts',{p_tenant:props.tenant,p_property:props.property,p_account:props.account}),props);if(alive.current)setSources(rows)}
 async function loadCashier(){setCashier(null);if(kind==='external_payment')setMethod('external');const result=readActiveCashiers(await hotelRpc('active_cashiers',{p_tenant:props.tenant,p_property:props.property}),props.tenant,props.property,props.actor,'manager');const mine=result.sessions.find(s=>s.is_mine);if(!alive.current)return;if(mine){setCashier({session:mine.session_id,drawer:mine.drawer});if(kind==='external_payment')setMethod('cash');setNotice('Your active drawer is selected.')}else setNotice('No active drawer assigned to you. Open one in Cashier before recording cash.')}
 function prepare(){try{const source=sources.find(s=>s.payment_id===target);if(kind==='external_refund'&&(!source||BigInt(cents(amount))>BigInt(source.available_minor)))throw Error('Select a receipt and an amount within its remaining balance.');setDraft(paymentRequest({version:1,actor:props.actor,tenant:props.tenant,property:props.property,account:props.account,request:crypto.randomUUID(),method,session:method==='cash'?cashier?.session??null:null,kind,amount:String(cents(amount)),target:kind==='external_refund'?target:null,reference:reference.trim(),reason:reason.trim()},props));setError('')}catch(e){setError(e instanceof Error?e.message:'Check payment details.')}}
 async function save(checkOnly=false){const r=pending??draft;if(!r||done||(!checkOnly&&r.cancellation))return;paymentRequest(r,props);sessionStorage.setItem(key,JSON.stringify(r));setPending(r);
  let id:string|null;try{id=checkOnly?paymentStatus(await hotelRpc('billing_payment_status',{p_tenant:r.tenant,p_property:r.property,p_account:r.account,p_request:r.request}),r):paymentReceipt(await hotelRpc('record_billing_payment',paymentArgs(r)),r)}catch{throw Error('Payment could not be confirmed. Check the result or retry this same entry. Do not record a replacement yet.')}
  if(!alive.current)return;if(!id){setNotice('No saved payment found. Retry this entry or cancel it before starting another.');return}
  sessionStorage.removeItem(key);setPending(null);setDraft(null);setDone(true);setNotice(r.kind==='external_refund'?'Refund recorded. No bank refund was initiated.':'Payment recorded. No card charge was initiated.');props.onSaved(id,r.kind);
 }
 async function cancel(){if(!pending)return;const r=paymentRequest({...pending,cancellation:pending.cancellation??cancelReason.trim()},props);sessionStorage.setItem(key,JSON.stringify(r));setPending(r);
  const v=await hotelRpc<Record<string,unknown>>('retire_billing_payment',{p_tenant:r.tenant,p_property:r.property,p_account:r.account,p_request:r.request,p_reason:r.cancellation,p_confirmed:true});
  if(v.tenant_id!==r.tenant||v.property_id!==r.property||v.account_id!==r.account||v.request_id!==r.request||v.actor_id!==r.actor||v.reason!==r.cancellation||v.retired!==true||v.money_moved!==false)throw Error('Cancellation could not be verified. Retry the saved cancellation.');
  if(!alive.current)return;sessionStorage.removeItem(key);setPending(null);setDraft(null);setNotice('Unsaved payment entry cancelled. No refund was made.');
 }
 const current=pending??draft;
 return <section className="pilot-settings" aria-label="Record company payment"><h3>Record payment or refund</h3><p>Record money already received or returned. This screen does not charge a card or send a bank refund.</p>
 {error&&<p role="alert">{error}</p>}{notice&&<p role="status">{notice}</p>}
 <fieldset disabled={busy||!!initial.error} style={{border:0,padding:0,margin:0}}>
 {!current&&!done&&<><label className="field">Entry type<select value={kind} onChange={e=>{setKind(e.target.value as 'external_payment'|'external_refund');setTarget('');setMethod('external')}}><option value="external_payment">Payment received</option><option value="external_refund">Refund already returned</option></select></label>{kind==='external_refund'&&<><button className="secondary" onClick={()=>void run(loadReceipts)}>Load receipts to refund</button><label className="field">Original receipt<select value={target} onChange={e=>{setTarget(e.target.value);const source=sources.find(s=>s.payment_id===e.target.value);if(source)setMethod(source.method)}}><option value="">Select receipt</option>{sources.map(s=><option key={s.payment_id} value={s.payment_id} disabled={s.available_minor==='0'}>{s.reference} · {s.method} · {billingDollars(s.available_minor)} available</option>)}</select></label></>}<label className="field">Payment method<select disabled={kind==='external_refund'} value={method} onChange={e=>setMethod(e.target.value as 'external'|'cash')}><option value="external">Paid elsewhere — bank, check or external terminal</option><option value="cash" disabled={!cashier}>Cash received</option></select></label><button className="secondary" onClick={()=>void run(loadCashier)}>Find my cash drawer</button>{cashier&&<p>Cash drawer: {cashier.drawer}</p>}
 <label className="field">Payment amount (USD)<input inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)}/></label><label className="field">Receipt or transaction reference<input maxLength={200} value={reference} onChange={e=>setReference(e.target.value)}/></label><label className="field">Payment note<textarea maxLength={500} value={reason} onChange={e=>setReason(e.target.value)}/></label><button className="primary" onClick={prepare}>Review payment</button></>}
 {current&&!done&&<><p>{current.kind==='external_refund'?'Refund returned':current.method==='cash'?'Cash received':'Payment completed elsewhere'} · {billingDollars(current.amount)}</p><p>Reference: {current.reference}</p><p>{current.reason}</p><button className="primary" disabled={!!current.cancellation} onClick={()=>void run(()=>save())}>{pending?'Retry saved payment':current.kind==='external_refund'?'Confirm refund returned':'Confirm payment received'}</button>{!pending&&<button className="secondary" onClick={()=>setDraft(null)}>Edit payment details</button>}
 {pending&&<><button className="secondary" onClick={()=>void run(()=>save(true))}>Check payment result</button><label className="field">Cancel unsaved payment reason<textarea maxLength={500} disabled={!!pending.cancellation} value={pending.cancellation??cancelReason} onChange={e=>setCancelReason(e.target.value)}/></label><p>Only an unsaved entry can be cancelled here. A recorded payment requires a separate refund or correction.</p><button className="secondary" onClick={()=>void run(cancel)}>{pending.cancellation?'Retry saved payment cancellation':'Cancel unsaved payment entry'}</button></>}</>}
 </fieldset>{busy&&<p role="status">Saving payment information…</p>}</section>;
}
